"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  CalendarCheck,
  FileText,
  HardHat,
  LogOut,
  QrCode,
  Snowflake,
  type LucideIcon,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Avatar } from "@/components/visual";
import { cn } from "@/lib/utils";
import type { Rol } from "@/lib/dominio";

type Seccion = { href: string; nombre: string; icono: LucideIcon; tambien?: string };

// La página de un equipo (/equipos/…) pertenece a "Equipos" para el admin y
// a "Mis equipos" para el técnico.
const SECCIONES: Record<Rol, Seccion[]> = {
  ADMIN: [
    { href: "/admin", nombre: "Asignaciones", icono: CalendarCheck },
    { href: "/admin/equipos", nombre: "Equipos", icono: Snowflake, tambien: "/equipos" },
    { href: "/admin/tecnicos", nombre: "Técnicos", icono: HardHat },
    { href: "/admin/bitacora", nombre: "Bitácora", icono: FileText },
  ],
  TECNICO: [
    { href: "/tecnico", nombre: "Mis equipos", icono: Snowflake, tambien: "/equipos" },
  ],
};

const NOMBRE_DE_ROL: Record<Rol, string> = {
  ADMIN: "Admin",
  TECNICO: "Técnico",
};

function Marca() {
  return (
    <span className="flex items-center gap-2.5 text-lg font-semibold tracking-tight">
      <span className="bg-brand text-brand-foreground flex size-8 items-center justify-center rounded-lg">
        <QrCode className="size-[1.1rem]" aria-hidden />
      </span>
      Mantenimiento QR
    </span>
  );
}

export function BarraLateral({
  rol,
  nombre,
  empresa,
  salir,
}: {
  rol: Rol;
  nombre: string;
  empresa: string;
  salir: () => Promise<void>;
}) {
  const ruta = usePathname();
  const secciones = SECCIONES[rol];

  const esActual = ({ href, tambien }: Seccion) =>
    href === "/admin"
      ? ruta === href
      : ruta.startsWith(href) || (!!tambien && ruta.startsWith(tambien));

  return (
    <>
      {/* Celular: marca, salir y las secciones en una fila. */}
      <header className="flex flex-col gap-3 px-4 pt-4 lg:hidden print:hidden">
        <div className="flex items-center justify-between gap-3">
          <Marca />
          <form action={salir}>
            <Button type="submit" variant="outline" className="bg-card h-9">
              <LogOut aria-hidden />
              Salir
            </Button>
          </form>
        </div>
        {secciones.length > 1 && (
          <nav aria-label="Secciones" className="-mx-4 flex gap-1 overflow-x-auto px-4">
            {secciones.map((seccion) => {
              const Icono = seccion.icono;
              return (
                <Link
                  key={seccion.href}
                  href={seccion.href}
                  aria-current={esActual(seccion) ? "page" : undefined}
                  className={cn(
                    "flex items-center gap-2 rounded-full px-3.5 py-2 text-sm font-medium whitespace-nowrap",
                    esActual(seccion)
                      ? "bg-foreground text-background"
                      : "bg-card text-muted-foreground",
                  )}
                >
                  <Icono className="size-4" aria-hidden />
                  {seccion.nombre}
                </Link>
              );
            })}
          </nav>
        )}
      </header>

      {/* Escritorio: panel blanco de alto completo. */}
      <aside className="sticky top-0 hidden h-dvh p-4 pr-2 lg:block print:hidden">
        <div className="bg-card flex h-full flex-col gap-8 rounded-3xl p-4">
          <div className="px-2 pt-3">
            <Marca />
          </div>

          <nav aria-label="Secciones" className="flex flex-col gap-1">
            {secciones.map((seccion) => {
              const actual = esActual(seccion);
              const Icono = seccion.icono;
              return (
                <Link
                  key={seccion.href}
                  href={seccion.href}
                  aria-current={actual ? "page" : undefined}
                  className={cn(
                    "flex items-center gap-3 rounded-full p-1.5 pr-4 font-medium transition-colors",
                    actual
                      ? "bg-background text-foreground"
                      : "text-muted-foreground hover:bg-background/60 hover:text-foreground",
                  )}
                >
                  <span
                    className={cn(
                      "flex size-9 items-center justify-center rounded-full",
                      actual && "bg-foreground text-background",
                    )}
                  >
                    <Icono className="size-[1.15rem]" aria-hidden />
                  </span>
                  {seccion.nombre}
                </Link>
              );
            })}
          </nav>

          <div className="mt-auto flex flex-col gap-1">
            <div className="bg-background flex items-center gap-3 rounded-2xl p-3">
              <Avatar nombre={nombre} />
              <div className="min-w-0 leading-tight">
                <p className="truncate font-medium">{nombre}</p>
                <p className="text-muted-foreground truncate text-sm">
                  {NOMBRE_DE_ROL[rol]}, {empresa}
                </p>
              </div>
            </div>
            <form action={salir}>
              <button
                type="submit"
                className="text-muted-foreground hover:bg-background/60 hover:text-foreground focus-visible:ring-ring/50 flex w-full cursor-pointer items-center gap-3 rounded-full p-1.5 pr-4 font-medium outline-none transition-colors focus-visible:ring-3"
              >
                <span className="flex size-9 items-center justify-center">
                  <LogOut className="size-[1.15rem]" aria-hidden />
                </span>
                Cerrar sesión
              </button>
            </form>
          </div>
        </div>
      </aside>
    </>
  );
}

import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  NOMBRE_DE_TIPO,
  TIPOS_SERVICIO,
  type TipoServicio,
} from "@/lib/dominio";

export function CamposServicio({
  prefijo,
  tipo,
  descripcion,
}: {
  prefijo: string;
  tipo?: TipoServicio | null;
  descripcion?: string;
}) {
  return (
    <>
      <fieldset className="@container/servicio flex min-w-0 flex-col gap-2">
        <legend className="mb-2 text-sm leading-none font-medium">
          Tipo de servicio
        </legend>
        <div className="grid gap-2 @min-[28rem]/servicio:grid-cols-3">
          {TIPOS_SERVICIO.map((valor) => (
            <label
              key={valor}
              className="has-checked:border-brand has-checked:bg-brand/15 has-focus-visible:ring-ring/50 flex min-h-11 cursor-pointer items-center gap-2 rounded-lg border px-2.5 text-sm font-medium has-focus-visible:ring-3"
            >
              <input
                type="radio"
                name="tipo"
                value={valor}
                defaultChecked={valor === tipo}
                required
                className="accent-primary size-4 shrink-0"
              />
              {NOMBRE_DE_TIPO[valor]}
            </label>
          ))}
        </div>
      </fieldset>

      <div className="flex flex-col gap-1.5">
        <Label htmlFor={`${prefijo}-descripcion`}>Trabajo realizado</Label>
        <Textarea
          id={`${prefijo}-descripcion`}
          name="descripcion"
          required
          minLength={5}
          maxLength={2000}
          defaultValue={descripcion}
          className="max-h-48 min-h-28 resize-y overflow-y-auto"
        />
      </div>
    </>
  );
}

/** Motivo obligatorio de una corrección o anulación (RS-13). */
export function CampoMotivo({ prefijo }: { prefijo: string }) {
  return (
    <div className="flex flex-col gap-1.5">
      <Label htmlFor={`${prefijo}-motivo`}>Motivo</Label>
      <Textarea
        id={`${prefijo}-motivo`}
        name="motivo"
        required
        minLength={5}
        maxLength={500}
      />
    </div>
  );
}

import Link from "next/link";
import {
  ArrowLeft,
  ArrowUpRight,
  Mail,
  MapPin,
  Snowflake,
  type LucideIcon,
} from "lucide-react";
import { cn } from "@/lib/utils";


const TONOS = {
  verde: "bg-brand/25 text-brand-foreground",
  naranja: "bg-amber-100 text-amber-800",
  azul: "bg-sky-100 text-sky-800",
  violeta: "bg-violet-100 text-violet-800",
  gris: "bg-secondary text-muted-foreground",
  oscuro: "bg-foreground text-background",
  // Sobre una tarjeta de color.
  claro: "bg-white/60 text-foreground",
} as const;

export type Tono = keyof typeof TONOS;

export function IconoEnCaja({
  icono: Icono,
  tono = "verde",
  grande = false,
}: {
  icono: LucideIcon;
  tono?: Tono;
  grande?: boolean;
}) {
  return (
    <span
      className={cn(
        "flex shrink-0 items-center justify-center rounded-xl",
        grande ? "size-14" : "size-11",
        TONOS[tono],
      )}
    >
      <Icono className={grande ? "size-7" : "size-5"} aria-hidden />
    </span>
  );
}

const PUNTOS = {
  verde: "bg-lime-500",
  naranja: "bg-amber-400",
  rojo: "bg-red-500",
  gris: "bg-neutral-400",
} as const;

export function Estado({
  tono,
  children,
}: {
  tono: keyof typeof PUNTOS;
  children: React.ReactNode;
}) {
  return (
    <span className="bg-secondary inline-flex w-fit shrink-0 items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium whitespace-nowrap">
      <span className={cn("size-1.5 rounded-full", PUNTOS[tono])} />
      {children}
    </span>
  );
}

export function iniciales(nombre: string): string {
  return nombre
    .split(" ")
    .slice(0, 2)
    .map((parte) => parte.charAt(0))
    .join("")
    .toUpperCase();
}

export function Avatar({
  nombre,
  chico = false,
}: {
  nombre: string;
  chico?: boolean;
}) {
  return (
    <span
      aria-hidden
      className={cn(
        "bg-foreground text-background flex shrink-0 items-center justify-center rounded-full font-medium",
        chico ? "size-6 text-[0.65rem]" : "size-11 text-sm",
      )}
    >
      {iniciales(nombre)}
    </span>
  );
}

export function Etiqueta({
  icono: Icono,
  mono = false,
  children,
}: {
  icono?: LucideIcon;
  mono?: boolean;
  children: React.ReactNode;
}) {
  return (
    <span
      className={cn(
        "bg-secondary inline-flex w-fit max-w-full items-center gap-1.5 rounded-full px-2.5 py-1 text-xs",
        mono && "font-mono",
      )}
    >
      {Icono && <Icono className="size-3.5 shrink-0" aria-hidden />}
      <span className="truncate">{children}</span>
    </span>
  );
}

export function Flecha() {
  return (
    <span className="group-hover:bg-foreground group-hover:text-background flex size-11 shrink-0 items-center justify-center rounded-xl bg-white/60 transition-colors">
      <ArrowUpRight className="size-5" aria-hidden />
    </span>
  );
}

export const tarjeta =
  "group focus-visible:ring-ring/60 flex flex-col rounded-2xl p-5 outline-none focus-visible:ring-3";

// todas las tarjetas de una lista miden igual
const tarjetaDeLista = "h-48 justify-between gap-6";

export const IconoDeEquipo = Snowflake;

/**
 * Enlace para regresar: una pastilla blanca con flecha, para que se note que
 * se puede usar. Va arriba de la página, fuera de las tarjetas.
 */
export function Volver({
  href,
  children,
}: {
  href: string;
  children: React.ReactNode;
}) {
  return (
    <Link
      href={href}
      className="bg-card hover:bg-foreground hover:text-background focus-visible:ring-ring/60 inline-flex w-fit items-center gap-2 rounded-full py-1.5 pr-3.5 pl-2.5 text-sm font-medium outline-none transition-colors focus-visible:ring-3 print:hidden"
    >
      <ArrowLeft className="size-4" aria-hidden />
      {children}
    </Link>
  );
}

export function TarjetaEquipo({
  href,
  equipo,
}: {
  href: string;
  equipo: { nombre: string; modelo: string; serie: string; ubicacion: string };
}) {
  return (
    <Link
      href={href}
      className={cn(tarjeta, tarjetaDeLista, "tarjeta-verde")}
    >
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          <p className="truncate text-lg leading-tight font-medium">
            {equipo.nombre}
          </p>
          <p className="text-foreground/60 mt-1 truncate text-sm">
            {equipo.modelo}
          </p>
        </div>
        <Flecha />
      </div>
      <div className="min-w-0">
        <p className="truncate font-mono text-2xl font-medium tracking-tight">
          {equipo.serie}
        </p>
        <p className="text-foreground/60 mt-1 flex items-center gap-1.5 text-sm">
          <MapPin className="size-4 shrink-0" aria-hidden />
          <span className="truncate">{equipo.ubicacion}</span>
        </p>
      </div>
    </Link>
  );
}

/**
 * Tarjeta de un técnico, con la misma estructura que la de un equipo. Va en
 * azul hielo para distinguir a las personas de los equipos; en gris si la
 * cuenta está desactivada.
 */
export function TarjetaTecnico({
  href,
  tecnico,
}: {
  href: string;
  tecnico: { nombre: string; correo: string; activo: boolean };
}) {
  return (
    <Link
      href={href}
      className={cn(
        tarjeta,
        tarjetaDeLista,
        tecnico.activo ? "tarjeta-hielo" : "tarjeta-gris",
      )}
    >
      <div className="flex items-start justify-between gap-3">
        <div className="flex min-w-0 items-center gap-3">
          <Avatar nombre={tecnico.nombre} />
          <div className="min-w-0">
            <p className="truncate text-lg leading-tight font-medium">
              {tecnico.nombre}
            </p>
            <p className="text-foreground/60 mt-1 truncate text-sm">Técnico</p>
          </div>
        </div>
        <Flecha />
      </div>
      <div className="flex min-w-0 flex-col items-start gap-2">
        <Estado tono={tecnico.activo ? "verde" : "gris"}>
          {tecnico.activo ? "Activo" : "Desactivado"}
        </Estado>
        <p className="text-foreground/60 flex max-w-full items-center gap-1.5 text-sm">
          <Mail className="size-4 shrink-0" aria-hidden />
          <span className="truncate">{tecnico.correo}</span>
        </p>
      </div>
    </Link>
  );
}

// Reglas puras de autenticación: sin base de datos ni cookies, para poder
// probarlas de forma aislada.
import { createHash, randomBytes } from "node:crypto";
import type { Rol } from "@/lib/dominio";

const MINUTO = 60_000;
const HORA = 60 * MINUTO;
const DIA = 24 * HORA;

/** Plazos de expiración por rol, en milisegundos (RS-04). */
export const PLAZOS: Record<Rol, { inactividad: number; absoluto: number }> = {
  TECNICO: { inactividad: 8 * HORA, absoluto: 7 * DIA },
  ADMIN: { inactividad: 30 * MINUTO, absoluto: 12 * HORA },
};

/** Token de sesión: 256 bits de un generador criptográfico. */
export function nuevoToken(): string {
  return randomBytes(32).toString("base64url");
}

/** En la base solo se guarda este hash, nunca el token. */
export function hashDeToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

export function sesionVigente(
  sesion: { ultimoUsoEn: Date; expiraEn: Date },
  rol: Rol,
  ahora: Date = new Date(),
): boolean {
  if (ahora >= sesion.expiraEn) return false;
  return ahora.getTime() - sesion.ultimoUsoEn.getTime() < PLAZOS[rol].inactividad;
}

export const LONGITUD_MINIMA = 12;
export const LONGITUD_MAXIMA = 200;

// Muestra corta de las más usadas; se comparan sin mayúsculas.
const COMUNES = new Set([
  "123456789012", "1234567890123", "contraseña123", "contrasena123",
  "password1234", "password12345", "qwertyuiop12", "qwerty123456",
  "administrador", "administrador1", "mantenimiento", "bienvenido123",
  "iloveyou1234", "abcdefghijkl", "111111111111", "000000000000",
]);

/** Devuelve el motivo del rechazo, o null si la contraseña es aceptable. */
export function validarPassword(password: string): string | null {
  if (password.length < LONGITUD_MINIMA) {
    return `Usa al menos ${LONGITUD_MINIMA} caracteres.`;
  }
  if (password.length > LONGITUD_MAXIMA) {
    return `Usa como máximo ${LONGITUD_MAXIMA} caracteres.`;
  }
  if (COMUNES.has(password.toLowerCase())) {
    return "Esa contraseña es muy común. Elige otra.";
  }
  return null;
}
